using System;using System.IO;using System.Linq;
namespace IrisDesktop {
 public static class GoalManagementFixture {
  static ProgressScope Scope(){return new ProgressScope{environment="development",accountId="synthetic-account",characterId="synthetic-character"};}
  static void Need(bool value,string reason){if(!value)throw new Exception(reason);}
  static ProgressMutation Goal(string id,long quantity){return new ProgressMutation{kind="CreateGoal",scope=Scope(),goalId=id,sourcePlanId="synthetic-plan",action="crafting",displayName="synthetic-sword",targetQuantity=quantity};}
  static ProgressMutation Cancel(string id){return new ProgressMutation{kind="SetLifecycle",scope=Scope(),goalId=id,lifecycle="cancelled"};}
  static ProgressMutation Bind(string id){return new ProgressMutation{kind="BindPreparedRequest",scope=Scope(),goalId=id,requestId=Guid.NewGuid().ToString("D"),action="crafting",displayName="synthetic-sword",craftCount=1,outputPerCraft=1,expectedOutput=1,preparedAt=1,expiresAt=2};}
  public static void Run(string root){
   var store=new DesktopErgonProgressStore(Path.Combine(root,"preserve"),"development");var id=Guid.NewGuid().ToString("D");Need(store.Commit(Goal(id,100),0,Guid.NewGuid()).status=="committed","create");var op=Guid.NewGuid();Need(store.Commit(Cancel(id),1,op).status=="committed","cancel");Need(store.Commit(Cancel(id),1,op).status=="already-applied","cancel replay");var reopened=new DesktopErgonProgressStore(Path.Combine(root,"preserve"),"development");var saved=reopened.Load(Scope());Need(saved.revision==2&&saved.view.goals.Single().targetQuantity==100&&saved.view.goals.Single().lifecycle=="cancelled","restart preserved");Need(reopened.Commit(Bind(id),2,Guid.NewGuid()).status=="rejected","cancelled binding allowed");Console.WriteLine("PASS G01 cancellation preserves original target and restart history, idempotent replay, no new binding");
   var conflict=new DesktopErgonProgressStore(Path.Combine(root,"cas"),"development");id=Guid.NewGuid().ToString("D");Need(conflict.Commit(Goal(id,4),0,Guid.NewGuid()).status=="committed","CAS create");Need(conflict.Commit(Bind(id),1,Guid.NewGuid()).status=="committed","CAS binding");var before=File.ReadAllBytes(conflict.FilePath);Need(conflict.Commit(Cancel(id),1,Guid.NewGuid()).status=="conflict","stale cancel accepted");Need(before.SequenceEqual(File.ReadAllBytes(conflict.FilePath))&&conflict.Load(Scope()).view.goals.Single().lifecycle=="active","CAS rewrote existing request");Console.WriteLine("PASS G02 request added after precheck makes old-revision cancel conflict without overwriting history");
   var foreign=Cancel(id);foreign.scope.characterId="foreign";Need(conflict.Commit(foreign,2,Guid.NewGuid()).status=="rejected"&&before.SequenceEqual(File.ReadAllBytes(conflict.FilePath)),"foreign cancelled");Console.WriteLine("PASS G03 foreign character cannot cancel or alter ciphertext");
   var fork=new DesktopErgonProgressStore(Path.Combine(root,"boundary"),"development");id=Guid.NewGuid().ToString("D");Need(fork.Commit(Goal(id,100),0,Guid.NewGuid()).status=="committed","boundary create");Need(fork.Commit(Cancel(id),1,Guid.NewGuid()).status=="committed","boundary cancel");Need(fork.Commit(Goal(Guid.NewGuid().ToString("D"),70),2,Guid.NewGuid()).status=="committed","candidate A");Need(fork.Commit(Goal(Guid.NewGuid().ToString("D"),60),3,Guid.NewGuid()).status=="rejected","candidate B blocked");Need(fork.Load(Scope()).view.goals.Count(g=>g.lifecycle=="active")==1,"existing contract changed");Console.WriteLine("PASS G04 strengthened live CreateGoal uniqueness closes prior duplicate replacement boundary");
  }
 }
}
